import{H as e,V as t,et as n,j as r}from"./chunks/framework.Dj60FFN6.js";var i=JSON.parse(`{"title":"[Limiti della probabilità classica]","description":"","frontmatter":{},"headers":[],"relativePath":"lezioni/l_calcolo-delle-probabilita/lc/lcdg.md","filePath":"lezioni/l_calcolo-delle-probabilita/lc/lcdg.md"}`),a={name:`lezioni/l_calcolo-delle-probabilita/lc/lcdg.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 class="text-red-darken-1" id="limiti-della-probabilita-classica" tabindex="-1">[Limiti della probabilità classica] <a class="header-anchor" href="#limiti-della-probabilita-classica" aria-label="Permalink to “[Limiti della probabilità classica]”">​</a></h1><p>La teoria classica della probabilità è una teoria &quot;a priori&quot;, cioè indica quale probabilità ha un evento che ancora deve accadere, però tutti i possibili esiti di un evento debbono essere ugualmente possibili e qui abbiamo una grossa difficoltà.</p><p><strong>Non è possibile nel mondo reale avere l&#39;esatta uguale possibilità fra eventi diversi</strong></p><blockquote><p>Per quanto un dado sia fatto bene, magari a livello microscopico, i suoi spigoli e le sue facce saranno tra loro differenti.</p><p>Sarà sufficiente che un tavolo di una roulette sia leggermente non in orizzontale, oppure che la ruota sia leggermente deformata per avere la maggior uscita di certi numeri piuttosto che di certi altri.</p><p>Osservate un&#39;estrazione di numeri al lotto: vedrete che in certe ruote escono di più i numeri bassi ed in altre di più i numeri alti; questo penso sia dovuto al fatto che nel primo caso sono stati introdotti i numeri partendo dal <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>90</mn></mrow><annotation encoding="application/x-tex">90</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">90</span></span></span></span> fino ad arrivare all&#39; <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>1</mn></mrow><annotation encoding="application/x-tex">1</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">1</span></span></span></span>, mentre nel secondo caso i numeri sono stati introdotti nell&#39;urna in ordine crescente e, per quanto si mescoli, qualcosa resta.</p></blockquote><p><strong>Esistono problemi per cui non è possibile applicare la probabilità classica:</strong></p><blockquote><p>Ad esempio, se dico che la squadra <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>A</mi></mrow><annotation encoding="application/x-tex">A</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal">A</span></span></span></span> ha il doppio di possibilità di vincere una determinata partita rispetto alla squadra <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>B</mi></mrow><annotation encoding="application/x-tex">B</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0502em;">B</span></span></span></span>, non si capisce come tale probabilità sia ricavata.</p><p>Se parlo di colpire un piattello con un colpo di fucile non posso applicare la probabilità classica.</p><p>Come posso definire la probabilità di sentire il segnale di occupato facendo un numero di telefono?</p></blockquote><p><strong>In problemi scientifici e tecnologici la probabilità classica incontra difficoltà insuperabili</strong></p><blockquote><p>Ad esempio è quasi impossibile determinare la probabilità per un singolo elettrone di fare un certo salto di orbitale oppure per un neutrone di collidere con un nucleo di uranio utilizzando la probabilità classica; e le cose peggiorano considerando oggetti ancora più piccoli quali i quark.</p></blockquote><p><strong>Esistono anche problemi in cui il numero di risultati possibili è infinito e quindi occorre introdurre dei nuovi concetti per poterli affrontare</strong></p><p>Per questi motivi è necessario introdurre nuovi tipi di probabilità che, conservando comunque i risultati della probabilità classica, permettano di superare le difficoltà qui sopra elencate.</p>`,10)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};